import{_ as o,r as t,o as i,c as l,e,a as p,s as c}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Media Manager - October CMS User Guide","titleTemplate":false,"description":"Upload an image and display it on your page","frontmatter":{"subtitle":"Upload an image and display it on your page"},"headers":[{"level":2,"title":"Navigate to the Media Tab","slug":"navigate-to-the-media-tab","link":"#navigate-to-the-media-tab","children":[]},{"level":2,"title":"Upload an Image","slug":"upload-an-image","link":"#upload-an-image","children":[]},{"level":2,"title":"Copy the File Path","slug":"copy-the-file-path","link":"#copy-the-file-path","children":[]},{"level":2,"title":"Display the Image on a Page","slug":"display-the-image-on-a-page","link":"#display-the-image-on-a-page","children":[]},{"level":2,"title":"Adding Media to Content Files","slug":"adding-media-to-content-files","link":"#adding-media-to-content-files","children":[]},{"level":2,"title":"How the |media Filter Works","slug":"how-the-media-filter-works","link":"#how-the-media-filter-works","children":[]},{"level":2,"title":"The Editor Section is Complete","slug":"the-editor-section-is-complete","link":"#the-editor-section-is-complete","children":[]}],"relativePath":"user-guide/quickstart/editor/media-manager.md","filePath":"user-guide/quickstart/editor/media-manager.md"}'),r={name:"user-guide/quickstart/editor/media-manager.md"};function u(d,a,g,h,m,k){const n=t("pre-heading"),s=t("post-heading");return i(),l("div",null,[e(n),a[0]||(a[0]=p("h1",null,"Media Manager",-1)),e(s),a[1]||(a[1]=c(`<p>The <strong>Media Manager</strong> is October CMS&#39;s built-in file library. It gives you a central place to upload, organize, and browse images, documents, and other files. Any file you upload here is available to use across your entire site.</p><h2 id="navigate-to-the-media-tab"><a href="#navigate-to-the-media-tab" class="header-anchor">#</a> Navigate to the Media Tab</h2><ol><li>Click <strong>Media</strong> in the top navigation menu.</li><li>You will see an empty library with a folder tree on the left and the main file area on the right.</li></ol><p>This is where all your shared media files live: photos, logos, PDFs, anything your site needs.</p><h2 id="upload-an-image"><a href="#upload-an-image" class="header-anchor">#</a> Upload an Image</h2><ol><li>Click the <strong>Upload</strong> button in the toolbar (or drag a file from your computer directly into the Media Manager window).</li><li>Select any image from your computer, such as a photo, a logo, or anything you like.</li><li>Wait for the upload to complete. The image will appear in the file list.</li></ol><div class="custom-block tip"><p>You can create folders to keep things organized. Click the <strong>New Folder</strong> button and give it a descriptive name like <code>images</code> or <code>blog</code>. For this tutorial, uploading to the root folder is fine.</p></div><h2 id="copy-the-file-path"><a href="#copy-the-file-path" class="header-anchor">#</a> Copy the File Path</h2><ol><li>Click on the image you just uploaded to select it.</li><li>Look for the file path displayed in the details panel. It will be something like <code>my-image.jpg</code> (or <code>images/my-image.jpg</code> if you put it in a folder).</li><li>Copy this path or remember it. You will need it in the next step.</li></ol><h2 id="display-the-image-on-a-page"><a href="#display-the-image-on-a-page" class="header-anchor">#</a> Display the Image on a Page</h2><ol><li>Navigate to <strong>Editor → Pages</strong> and open <strong>About</strong>.</li><li>Add an image tag using the <code>|media</code> filter. Update the markup to include your image:</li></ol><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-3xl font-bold mb-4<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>About<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-lg text-gray-600 mb-6<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    This is another page using the same layout. The header, navigation,
    and footer are identical. Only the content area changed.
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span>
    <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>my-image.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>media <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>My uploaded image<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>rounded-lg shadow-md max-w-full mt-6<span class="token punctuation">&quot;</span></span>
<span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mt-6<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Go back to the <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>home<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>page <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>text-blue-600 underline<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>home page<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>.
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><ol start="3"><li>Replace <code>my-image.jpg</code> with the actual file path you copied.</li><li>Click <strong>Save</strong> and preview the page.</li></ol><p>Your image should now appear on the page, styled with rounded corners and a subtle shadow.</p><h2 id="adding-media-to-content-files"><a href="#adding-media-to-content-files" class="header-anchor">#</a> Adding Media to Content Files</h2><p>You can also insert images directly into content files using the Markdown editor&#39;s built-in toolbar.</p><ol><li>Navigate to <strong>Editor → Content</strong> and open <strong>my-content.md</strong>.</li><li>Place your cursor where you want the image to appear.</li><li>Click the <strong>Image</strong> icon in the Markdown toolbar.</li><li>Select <strong>Browse Media Library</strong>. The Media Manager opens as a popup.</li><li>Click the image you uploaded earlier and confirm.</li><li>The image is inserted into your Markdown content automatically.</li><li>Click <strong>Save</strong> and preview the home page to see the image rendered inside the content block.</li></ol><p>This is a quick way to add images without writing any markup. The editor handles the <code>|media</code> path for you.</p><h2 id="how-the-media-filter-works"><a href="#how-the-media-filter-works" class="header-anchor">#</a> How the |media Filter Works</h2><p>The <code>|media</code> filter takes a path relative to your media storage root and converts it to a full URL:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>my-image.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>media <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>This outputs something like <code>https://yoursite.com/storage/app/media/my-image.jpg</code>. You should always use this filter instead of hardcoding paths. It ensures your media URLs are correct regardless of your server configuration.</p><div class="custom-block aside"><p>For the full reference on the Media Manager, including image resizing and cloud storage configuration, see the <a href="./../../../4.x/cms/media/introduction.html">Media Manager</a> documentation.</p></div><h2 id="the-editor-section-is-complete"><a href="#the-editor-section-is-complete" class="header-anchor">#</a> The Editor Section is Complete</h2><p>You now know the fundamentals of the October CMS editor: themes, layouts, pages, content blocks, and the media manager. Everything you build from here will use these concepts.</p><p>Continue to <a href="./../content-management/tailor-introduction.html">Content Management</a> to learn how to create structured content types like blog posts and team members using Tailor blueprints.</p>`,26))])}const w=o(r,[["render",u]]);export{y as __pageData,w as default};
